mapper.select:
select *
from appointment
where slot_id = #{slotId}
and patient_id = #{patientId}
and department_id = #{departmentId}
and status = 0

select a.appointment_id, a.patient_id, a.patient_name, a.doctor_id, a.doctor_name, a.department_id, a.department_name, a.slot_id, a.visit_date, a.period, a.display_no, a.fee, a.contact_phone, a.payee_code, a.status from appointment a join patient_exp pe on a.patient_id = pe.patient_id where pe.belonging_uid = #{belongingUid}
and a.contact_phone like concat('%', #{dto.contactPhone}, '%')
and a.doctor_name like concat('%', #{dto.doctorName}, '%')
and a.department_id = #{dto.departmentId}
and a.visit_date = #{dto.visitDate}
and a.status = #{dto.status}
order by a.visit_date desc, a.display_no
